# A timing decorator that preserves metadata
import functools, time, logging

logging.basicConfig(level=logging.INFO)
log = logging.getLogger(__name__)

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            log.info("%s took %.3fs", func.__name__, time.perf_counter() - start)
    return wrapper

@timed
def process_report(rows):
    "Process a report."
    return sum(rows)

process_report([1, 2, 3])
print(process_report.__name__, process_report.__doc__)  # process_report Process a report.
```

