import functools, random, time

def retry(attempts=3, exceptions=(ConnectionError,), base_delay=0.5):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == attempts:
                        raise
                    time.sleep(base_delay * 2 ** (attempt - 1) + random.uniform(0, 0.1))
        return wrapper
    return decorator

