# Registration decorator: build a handler registry
HANDLERS = {}

def register(report_type):
    def decorator(func):
        HANDLERS[report_type] = func   # side effect at import time
        return func                    # return the original unchanged
    return decorator

@register("amazon_orders")
def handle_amazon_orders(df):
    return f"amazon: {len(df)} rows"

print(HANDLERS["amazon_orders"]([1, 2]))
