# Async-aware decorator with typed signature (Python 3.12 generics)
import asyncio, functools, time
from collections.abc import Awaitable, Callable

def atimed[**P, R](func: Callable[P, Awaitable[R]]) -> Callable[P, Awaitable[R]]:
    @functools.wraps(func)
    async def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        start = time.perf_counter()
        try:
            return await func(*args, **kwargs)
        finally:
            print(f"{func.__name__}: {time.perf_counter() - start:.3f}s")
    return wrapper

@atimed
async def download(url: str) -> int:
    await asyncio.sleep(0.1)
    return 200

asyncio.run(download("https://example.com"))
